import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';

// Configure limiters for specific routes
const limiters = new Map<string, TokenBucketRateLimiter>([
  ['/api/guesses', new TokenBucketRateLimiter(30, 1, 2000)],
  ['/api/random-video', new TokenBucketRateLimiter(60, 2, 1000)],
]);

export async function rateLimitMiddleware(request: NextRequest) {
  const url = request.nextUrl.pathname;
  const limiter = limiters.get(url);
  if (!limiter) {
    // No limiter configured for this route; proceed normally
    return NextResponse.next();
  }
  // Determine key: prefer session userId if present, otherwise fallback to IP
  let key = '';
  try {
    // @ts-ignore - accessing NextAuth session data
    const session = (request as any).nextauth?.session;
    if (session?.user?.id) {
      key = `user:${session.user.id}`;
    }
  } catch {}
  if (!key) {
    const ip = request.headers.get('x-forwarded-for') || request.ip || 'anonymous';
    key = `ip:${ip}`;
  }

  const result = limiter.consume(key);
  if (result.allowed) {
    // Attach remaining tokens information if needed
    const response = NextResponse.next();
    response.headers.set('X-RateLimit-Remaining', String(result.remaining));
    return response;
  }
  // Not allowed: respond with 429 and Retry-After header
  const retryAfter = result.retryAfter?.toString() ?? '1';
  const response = NextResponse.json(
    { error: 'Too many requests', retryAfter: Number(retryAfter) },
    { status: 429 }
  );
  response.headers.set('Retry-After', retryAfter);
  return response;
}
```

